from __future__ import absolute_import
from taf.selenium.sc.pages.configuration_management.edit_configuration import ParameterEditorPage, ActivationPage
from taf.selenium.sc.pages.configuration_management.view_configuration import ViewConfigurationPage
from taf.selenium.sc.pages.configuration_management.save_configuration_file import SaveScfFilePage
from taf.selenium.sc.pages.configuration_management.load_configuration_file import ConfigureFromaFilePage


class ConfigurationManagement(object):
    def __init__(self, driver, download_checker):
        self._parameter_editor = ParameterEditorPage(driver)
        self._activation = ActivationPage(driver)
        self._view_configuration = ViewConfigurationPage(driver)
        self._save_scf_file = SaveScfFilePage(driver, download_checker)
        self._configure_from_a_file = ConfigureFromaFilePage(driver)

    @property
    def parameter_editor(self):
        return self._parameter_editor

    @property
    def activation(self):
        return self._activation

    @property
    def view_configuration(self):
        return self._view_configuration

    @property
    def save_scf_file(self):
        return self._save_scf_file

    @property
    def load_configuration_file(self):
        return self._configure_from_a_file
